<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import KrigingMetrics from '../components/KrigingMetrics.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'空间推断底稿 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 地块归档" title="让预测，带着参数与限制一并归档。" note="管理员批准后保存不可变快照。CSV包括米制坐标、预测、空间方差、原始方差、权重和、mu、模型参数与输入哈希。"/><Notice :message="error"/><div class="two-col"><section><h2>地块复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待管理员批准'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准空间复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成空间快照</button></div></article></section><section><h2>批准底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED FIELD RECORD</p><h3>{{r.title}}</h3><p>{{r.snapshot.result.points.length}}采样 / {{r.snapshot.result.queries.length}}待估 · {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载预测 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看锁定模型</button></div><KrigingMetrics v-if="expanded===r.id" :result="r.snapshot.result"/></article></section></div></template>
